package ai.xzkj.recruitment.localconnector;
import ai.xzkj.recruitment.audit.AuditService;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;
@Component class LocalConnectorProductionApprovalWatchdog{private final LocalConnectorProductionApprovalRepository approvals;private final LocalConnectorCapabilityRepository capabilities;private final AuditService audit;LocalConnectorProductionApprovalWatchdog(LocalConnectorProductionApprovalRepository a,LocalConnectorCapabilityRepository c,AuditService audit){approvals=a;capabilities=c;this.audit=audit;}@Scheduled(fixedDelayString="${app.browser.production-approval-watchdog-interval:30s}",initialDelayString="${app.browser.production-approval-watchdog-interval:30s}")@Transactional void expire(){Instant now=Instant.now();for(LocalConnectorProductionApproval x:approvals.findByStatusAndExpiresAtBefore("APPROVED",now)){x.expire(now);capabilities.findByDeviceIdAndCapability(x.getDevice().getId(),x.getActionType()).ifPresent(c->c.revokeProduction("低配额生产批准已到期",now));audit.systemSuccess("EXPIRE_CONNECTOR_PRODUCTION_APPROVAL","CONNECTOR_PRODUCTION_APPROVAL",x.getId(),x.getDevice().getBossAccount().getDisplayName(),x.getActionType()+" 批准到期，能力已锁定");}}}
